define(['core/log','core/notification','core/str'],function(Log,Notification,Str){return{init:function(){document.querySelectorAll('.videotrack-delete-preset-form').forEach(function(form){form.addEventListener('submit',function(e){if(form.dataset.confirmed==='1'){return;}e.preventDefault();var button=form.querySelector('[data-confirm]');var msg=(button&&button.getAttribute('data-confirm'))||'Delete this preset?';Str.get_strings([{key:'confirm',component:'moodle'},{key:'delete',component:'moodle'},{key:'cancel',component:'moodle'}]).then(function(strings){return Notification.confirm(strings[0],msg,strings[1],strings[2],function(){form.dataset.confirmed='1';form.submit();});}).catch(function(){return Notification.confirm('Confirm',msg,'Delete','Cancel',function(){form.dataset.confirmed='1';form.submit();});});});});Log.debug('mod_videotrack/presets: initialised');}};});